      "tipo": "CPU",
      "causa_raiz": "Uso repetitivo de GameObject.FindObjectsOfType<GameObject>() dentro do método Update(), forçando a CPU a varrer toda a árvore de GameObjects da cena múltiplas vezes a cada frame, gerando picos de processamento de até 240ms.",
      "codigo_refatorado": "using System;
using System.Collections.Generic;
using UnityEngine;

namespace PerformanceAdvisor.StressTest
{
    public class StressTestScene : MonoBehaviour
    {
        public bool stressGc = false;
        public bool stressCpu = false;
        public bool stressDraw = false;
        public GameObject testPrefab;
        [Range(1, 20)] public float spawnRadius = 10f;
        [Range(1, 50)] public int cubesPerFrame = 1;
        public bool useUniqueMaterials = false;
        [Range(1, 512)] public int cpuScansPerFrame = 1;
        public int emptyObjects = 0;
        public int gcConcatIterations = 0;
        public int gcArrayAllocs = 0;
        public int overdrawLayers = 0;
        public Material overdrawMaterial;
        [Range(0, 2000)] public int prepopulateCount = 0;

        private readonly List<GameObject> activeInstances = new List<GameObject>();
        private MaterialPropertyBlock propertyBlock;
        private static readonly int ColorPropertyId = Shader.PropertyToID("_Color");

        private void Awake()
        {
            propertyBlock = new MaterialPropertyBlock();
        }

        private void Start()
        {
            if (prepopulateCount > 0 && testPrefab != null)
            {
                for (int i = 0; i < prepopulateCount; i++)
                {
                    SpawnOne();
                }
            }

            for (int i = 0; i < emptyObjects; i++)
            {
                var emptyGo = new GameObject("Empty_" + i);
                activeInstances.Add(emptyGo);
            }
        }

        private void Update()
        {
            if (stressCpu && activeInstances.Count > 0)
            {
                int scanCount = Mathf.Min(cpuScansPerFrame, 10);
                for (int k = 0; k < scanCount; k++)
                {
                    int index = UnityEngine.Random.Range(0, activeInstances.Count);
                    var obj = activeInstances[index];
                    if (obj != null)
                    {
                        var tr = obj.transform.position;
                    }
                }
            }

            if (stressDraw && testPrefab != null)
            {
                int n = Mathf.Max(1, cubesPerFrame);
                for (int i = 0; i < n; i++)
                {
                    SpawnOne();
                }
            }
        }

        private void SpawnOne()
        {
            var clone = Instantiate(
                testPrefab,
                UnityEngine.Random.insideUnitSphere * spawnRadius,
                Quaternion.identity);
            activeInstances.Add(clone);

            if (useUniqueMaterials)
            {
                var renderer = clone.GetComponent<Renderer>();
                if (renderer != null)
                {
                    renderer.GetPropertyBlock(propertyBlock);
                    propertyBlock.SetColor(ColorPropertyId, new Color(UnityEngine.Random.value, UnityEngine.Random.value, UnityEngine.Random.value));
                    renderer.SetPropertyBlock(propertyBlock);
                }
            }
        }
    }
}",
      "explicacao_didatica": "O comando FindObjectsOfType é uma das operações mais lentas da Unity, pois ele percorre todos os objetos ativos na memória para checar seus tipos. Ao executá-lo repetidamente dentro do Update, o processador fica sobrecarregado procurando o que já existe. Para resolver, mantemos uma lista cacheada em memória e registramos os objetos assim que são instanciados, eliminando a busca custosa a cada quadro."
    },
    {
      "tipo": "GC",
      "causa_raiz": "Concatenação de strings em laço de repetição ('s += i.ToString()') e instanciação repetida de arrays de objetos no Update(), gerando mais de 10 MB de lixo na memória heap a cada frame e travando o jogo com coletas de lixo frequentes de até 16ms.",
      "codigo_refatorado": "using System;
using System.Collections.Generic;
using System.Text;
using UnityEngine;

namespace PerformanceAdvisor.StressTest
{
    public class StressTestScene : MonoBehaviour
    {
        public bool stressGc = false;
        public bool stressCpu = false;
        public bool stressDraw = false;
        public GameObject testPrefab;
        [Range(1, 20)] public float spawnRadius = 10f;
        [Range(1, 50)] public int cubesPerFrame = 1;
        public bool useUniqueMaterials = false;
        [Range(1, 512)] public int cpuScansPerFrame = 1;
        public int emptyObjects = 0;
        public int gcConcatIterations = 0;
        public int gcArrayAllocs = 0;
        public int overdrawLayers = 0;
        public Material overdrawMaterial;
        [Range(0, 2000)] public int prepopulateCount = 0;

        private readonly List<GameObject> activeInstances = new List<GameObject>();
        private MaterialPropertyBlock propertyBlock;
        private static readonly int ColorPropertyId = Shader.PropertyToID("_Color");
        private StringBuilder cachedStringBuilder = new StringBuilder(256);

        private void Awake()
        {
            propertyBlock = new MaterialPropertyBlock();
        }

        private void Start()
        {
            if (prepopulateCount > 0 && testPrefab != null)
            {
                for (int i = 0; i < prepopulateCount; i++)
                {
                    SpawnOne();
                }
            }

            for (int i = 0; i < emptyObjects; i++)
            {
                cachedStringBuilder.Clear();
                cachedStringBuilder.Append("Empty_").Append(i);
                var emptyGo = new GameObject(cachedStringBuilder.ToString());
                activeInstances.Add(emptyGo);
            }
        }

        private void Update()
        {
            if (stressDraw && testPrefab != null)
            {
                int n = Mathf.Max(1, cubesPerFrame);
                for (int i = 0; i < n; i++)
                {
                    SpawnOne();
                }
            }
        }

        private void SpawnOne()
        {
            var clone = Instantiate(
                testPrefab,
                UnityEngine.Random.insideUnitSphere * spawnRadius,
                Quaternion.identity);
            activeInstances.Add(clone);

            if (useUniqueMaterials)
            {
                var renderer = clone.GetComponent<Renderer>();
                if (renderer != null)
                {
                    renderer.GetPropertyBlock(propertyBlock);
                    propertyBlock.SetColor(ColorPropertyId, new Color(UnityEngine.Random.value, UnityEngine.Random.value, UnityEngine.Random.value));
                    renderer.SetPropertyBlock(propertyBlock);
                }
            }
        }
    }
}",
      "explicacao_didatica": "Em C#, o texto (string) é imutável: toda vez que você faz 's += ...', uma nova string é criada e a antiga é descartada. Em 1000 repetições dentro do Update, criam-se milhares de pequenas memórias descartáveis por segundo. Quando a memória enche, a Unity pausa o jogo para limpar a sujeira (Garbage Collector). Ao remover alocações desnecessárias no Update e utilizar ferramentas como StringBuilder ou reutilização de buffers, o lixo gerado vai para zero e os travamentos somem."
    }
  ],
  "dicas_level_design": null
}

